import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen0Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteEndArray_AfterStartArray() throws IOException {
        // Arrange: Start an array to create a context hierarchy
        tokenBuffer.writeStartArray();

        // Act
        tokenBuffer.writeEndArray();

        // Assert: Verify the token appended is END_ARRAY
        // We use asParser() to inspect the generated buffer content
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_NestedArrays() throws IOException {
        // Arrange: Create nested structure [ [ ] ]
        tokenBuffer.writeStartArray(); // Level 0
        tokenBuffer.writeStartArray(); // Level 1

        // Act: Close inner array
        tokenBuffer.writeEndArray(); 

        // Assert: Verify inner array is closed, but outer context still exists
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_ARRAY, parser.nextToken()); // Level 0
        assertEquals(JsonToken.START_ARRAY, parser.nextToken()); // Level 1
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());   // Level 1 closed

        // Act: Close outer array
        tokenBuffer.writeEndArray();
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());   // Level 0 closed
    }

    @Test
    public void testWriteEndArray_WithObject() throws IOException {
        // Arrange: Create structure {"a": []}
        tokenBuffer.writeStartObject();
        tokenBuffer.writeFieldName("a");
        tokenBuffer.writeStartArray();

        // Act
        tokenBuffer.writeEndArray();
        tokenBuffer.writeEndObject();

        // Assert
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("a", parser.getCurrentName());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_UnbalancedRoot() throws IOException {
        // Arrange: Start with nothing (root context has no parent)
        // The code says: if (c != null) { _writeContext = c; }
        // This test ensures no NullPointerException occurs when calling writeEndArray on a root level

        // Act
        tokenBuffer.writeEndArray();

        // Assert
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_DeeplyNestedContext() throws IOException {
        // Arrange: Deeply nest to ensure context pointer moves up correctly
        tokenBuffer.writeStartObject(); // Context 1
        tokenBuffer.writeStartArray();  // Context 2
        tokenBuffer.writeStartArray();  // Context 3

        // Act
        tokenBuffer.writeEndArray(); // Should return to Context 2
        tokenBuffer.writeEndArray(); // Should return to Context 1
        tokenBuffer.writeEndObject(); // Should return to Root

        // Assert
        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }
}
